#THIS INTENDS TO DO THE OGW PLOT#import os#save_dir = os.path.expanduser("~/Desktop/python_plot")#os.makedirs(save_dir, exist_ok=True)import numpy as npimport matplotlib.pyplot as pltfrom scipy.special import sicifrom labellines import labelLine, labelLines# from scipy.stats import linregress#%%# ConstantsPi0 = 7e7xsIN = 0.001xsFIN = 200    xsnum = 300tIN = 0.01tFIN = 200tnum = 100sIN = -1sFIN = 1snum = 75HI = 1e-6h0 = 0.67ORD = 4.2e-5*h0**(-2)#%%# GridsxT = np.logspace(np.log10(xsIN), np.log10(xsFIN), xsnum)tT = np.logspace(np.log10(tIN), np.log10(tFIN), tnum)sT = np.linspace(sIN, sFIN, snum)# CN contractiondef contraction(t, s):    u = (t + s + 1) / 2    v = (t - s + 1) / 2    mu = (1 - u**2 - v**2) / (2 * v)    return (1 + mu**2) * (1 + ((-1 + v * mu)**2) / u**2)# Π(κ)def Pi(kappa):    if np.isscalar(kappa) and kappa >= 50:        return 0    if np.isscalar(kappa) and kappa == 0:        return np.inf    term1 = 1    term2 = (2 / kappa**3) * Pi0 * (        kappa**3 + (4 * kappa**2 - 3) * np.sin(2 * kappa) -        (kappa**2 - 6) * kappa * np.cos(2 * kappa))    term3 = (4 / kappa**6) * Pi0**2 * (kappa**2 + 1) * (        ((kappa**2 - 3) * np.sin(kappa) + 3 * kappa * np.cos(kappa))**2)    return term1 + term2 + term3 if kappa < 50 else 0#%%def f5(m):    arg = 1e-4 * xT[m]    Ci, Si = sici(arg)    return (Ci**2 + (np.pi / 2 + Si)**2)def sub(i, j):    return -contraction(tT[i], sT[j])def sub3(m, i, j):    t = tT[i]    s = sT[j]    u = (t + s + 1) / 2 * xT[m]    v = (t - s + 1) / 2 * xT[m]    return sub(i, j) * Pi(u) * Pi(v)#%%# Compute OGW2OGW2 = np.zeros(xsnum)for m in range(xsnum):    total = 0.0    for i in range(tnum):        for j in range(snum):            total += sub3(m, i, j) * tT[i] * sT[j]    OGW2[m] = total#%%# Final table that will give OGWprefactor =  2.e-48 *((tFIN / tIN)**(1 / (tnum - 1)) - 1)tab2_y = np.array([prefactor * f5(m)*OGW2[m]                    for m in range(xsnum)])tab2_x = xT#%%# --- Parameters: CHANGE THESE TO ADJUST THE TANGENT ---#x0 = 1.6e-2         # Central point around which to compute the tangent#fit_range = 0.9   # Fractional half-width: fit over [x0*(1 - fit_range), x0*(1 + fit_range)]# --- Select data in fit range ---#xmin = x0 * (1 - fit_range)#xmax = x0 * (1 + fit_range)#fit_mask = (tab2_x > xmin) & (tab2_x < xmax)#logx_fit = np.log10(tab2_x[fit_mask])#logy_fit = np.log10(tab2_y[fit_mask])# --- Linear fit in log-log space ---#slope, intercept, *_ = linregress(logx_fit, logy_fit)# --- Construct tangent line ---#x_tangent = np.logspace(np.log10(xmin), np.log10(xmax), 100)#y0 = 10**(slope * np.log10(x0) + intercept)  # anchor at x0#y_tangent = y0 * (x_tangent / x0)**slope#%%bpl = np.load('/Users/alisha/Documents/LISA_ET/Datafiles/BPLS/BPLS_lisa.npy')lisa = np.load('/Users/alisha/Documents/LISA_ET/Datafiles/lisanom.npy')bpl = bpl[bpl[:, 1] < 1e-5]bx1, bx2 = bpl[0,0], bpl[-1,0]by1, by2 = bpl[0,1], bpl[-1,1]# plt.loglog(lisa[:,0],lisa[:,1])#%%# Plot# fstar =5e-8fstar = 0.1plt.figure(figsize=(8, 5))plt.loglog(tab2_x*fstar, tab2_y,  linewidth=2.5, label=r'$\Omega_{\rm GW}(f)$')# plt.loglog(x_tangent, y_tangent, 'r--', linewidth=2.5,#            label=fr'Tangent $\propto f^{{{slope:.2f}}}$')plt.loglog((bpl[:,0]), (bpl[:,1]), label = "LISA BPLS", color = "green", linewidth=2.5)plt.loglog(lisa[:,0],lisa[:,1],'--',linewidth=2.5, label = "LISA nominal", color = "black")# Aestheticsplt.fill_between(bpl[:,0], bpl[:,1], y2=max(bpl[:,1]), where=(bpl[:,0] >= bx1) & (bpl[:,0] <= bx2), color='green', alpha=0.2)lines = plt.gca().get_lines()# labelLine(lines[-1], 1e-4, align = True)labelLines(lines[:3], xvals=[8e-2, 7e-2, 2e-2],align=True, yoffsets=[1.5e-11, 2e-9, 1e-8], outline_color="none")plt.xlabel(r'$f(Hz)$', fontsize=14)plt.ylabel(r'$\Omega_{\rm GW}(f)$', fontsize=14)#plt.title(r'Gravitational Wave Spectrum with Local Tangent Fit')plt.grid(True, which="both", ls="--", linewidth=0.5, alpha=0.4)# plt.xticks([1e-12,1e-11,1e-10, 1e-9, 1e-8, 1e-7, 1e-6], labels=[r'$10^{-12}$',r'$10^{-11}$',r'$10^{-10}$', r'$10^{-9}$', r'$10^{-8}$', r'$10^{-7}$',  r'$10^{-8}$'])plt.xlim(1e-5, 30)plt.ylim(1e-24,1e-5)plt.tick_params(axis='both', which='major', labelsize=13)# plt.legend(fontsize=10,loc='upper right')plt.tight_layout()plt.savefig('/Users/alisha/Documents/Magnetogenesis/Plots/plotOGW12.png', bbox_inches='tight')plt.show()#filename = os.path.join(save_dir, "plotOGW1.pdf")#plt.savefig(filename, format='pdf')# %%h2 = 0.68**2#NANOgravPTA = np.loadtxt("/Users/alisha/Documents/Vec_DM/datafiles/sensitivity_curves_NG15yr_fullPTA.txt",delimiter=',', skiprows=1)freqs = PTA[:, 0]h_c = PTA[:, 1] # characteristic strainS_eff = PTA[:, 2] #strain power spectral densityNano_GW = PTA[:, 3] #calculated using H0=67.4 km/s/Mpc = 67.4*1e3/1/3e22 s^-1 to match the paper # arxiv 2002.04615SKA = np.loadtxt("/Users/alisha/Documents/Vec_DM/datafiles/strain_SKA.dat", skiprows=10)freqska = 10**SKA[:,0]omegska = 10**SKA[:,1]/h2x1, x2 = freqska[0], freqska[-1]y1, y2 = omegska[0], omegska[-1]IPTA = np.loadtxt("/Users/alisha/Documents/Vec_DM/datafiles/strain_IPTA.dat", skiprows=10)freqipta = 10**IPTA[:,0]omegipta = 10**IPTA[:,1]/h2ix1, ix2 = freqipta[0], freqipta[-1]iy1, iy2 = omegipta[0], omegipta[-1]# %%fstar = 5e-8plt.figure(figsize=(8,5))plt.loglog(freqs, Nano_GW, label = r"NANOGrav", color = "indigo")plt.loglog(freqska, omegska, label = r"SKA", color = "black")plt.loglog(freqipta, omegipta, label = r"IPTA", color = "firebrick")plt.loglog(tab2_x*fstar, tab2_y,  linewidth=2.5, label=r'$\Omega_{\rm GW}(f)$')plt.vlines(x1, y1, y1 + 2, linestyle='--', color = 'black')plt.vlines(ix1, iy1, iy1 + 2, linestyle='--', color = 'firebrick')plt.ylabel(r"$\Omega_{GW}(f)$", fontsize = 14)plt.xlabel(r"f(Hz)", fontsize = 14)# plt.legend(loc = 0, 